const SQUARE_INVARIANT = 'x >= 0 && y >= 0 && (x*x+y == 0 || x*x+y == 1 || x*x+y == 4)';
const ROTATION_INVARIANT = 'x*x+y*y == 1 || x*x+y*y == 4 || x*x+y*y == 9';
const FACTOR_INVARIANT = 'x > 0 && y > 0 && 8 % y == 0 && (x*y == 6 || x*y == 12 || x*y == 24)';
const SEARCH_INVARIANT = 'x >= 0 && x <= y && y <= 8 && ((x <= 3 && y >= 3) || x == 4 || x == 5)';
const GCD_INVARIANT = 'x > 0 && y > 0 && x <= 8 && y <= 8 && (x < 6 || y < 6) && ((x % 2 == 0 && y % 2 == 0) || (x % 3 == 0 && y % 3 == 0))';
const FIBONACCI_INVARIANT = 'x > 0 && x <= y && y <= 6 && (x*x+x*y-y*y == 1 || x*x+x*y-y*y == -1 || x*x+x*y-y*y == 4 || x*x+x*y-y*y == -4 || x*x+x*y-y*y == 9 || x*x+x*y-y*y == -9)';
const PELL_INVARIANT = 'x >= 0 && y >= 0 && x <= 8 && y <= 6 && (x*x-2*y*y == 1 || x*x-2*y*y == -1 || x*x-2*y*y == 2 || x*x-2*y*y == -2 || x*x-2*y*y == 4 || x*x-2*y*y == -4)';

